{
  "name": "Andor 科学相机",
  "name_en": "Andor scientific camera",
  "manufacturer": "Andor",
  "description": "用于实验成像采集的科学相机，可进行曝光控制、图像帧读取、ROI（感兴趣区域）设置、缓冲区管理、传感器温度与快门相关控制，适用于显微成像等实验场景。",
  "description_en": "A scientific imaging camera for laboratory image acquisition, supporting exposure control, frame readout, ROI configuration, buffer management, sensor temperature handling, and shutter-related control for applications such as microscopy.",
  "actions": [
    {
      "action_name": "auto-Init",
      "description": "初始化相机。",
      "description_en": "Initialize the camera."
    },
    {
      "action_name": "auto-ExpReady",
      "description": "检查相机缓冲区中是否有待读取的图像帧。",
      "description_en": "Check whether image frames are waiting in the camera buffer."
    },
    {
      "action_name": "auto-CamReady",
      "description": "检查相机是否已初始化并处于可用状态。",
      "description_en": "Check whether the camera is initialized and ready."
    },
    {
      "action_name": "auto-ExtractColor",
      "description": "从相机缓冲区取出最旧的一帧并复制到提供的内存中。",
      "description_en": "Pull the oldest frame from the camera buffer and copy it into provided memory."
    },
    {
      "action_name": "auto-GetSerialNumber",
      "description": "获取相机序列号。",
      "description_en": "Get the camera serial number."
    },
    {
      "action_name": "auto-SetIntegTime",
      "description": "设置曝光时间。",
      "description_en": "Set the exposure time."
    },
    {
      "action_name": "auto-GetIntegTime",
      "description": "获取曝光时间。",
      "description_en": "Get the exposure time."
    },
    {
      "action_name": "auto-GetCCDWidth",
      "description": "获取传感器宽度（像素）。",
      "description_en": "Get the sensor width in pixels."
    },
    {
      "action_name": "auto-GetCCDHeight",
      "description": "获取传感器高度（像素）。",
      "description_en": "Get the sensor height in pixels."
    },
    {
      "action_name": "auto-GetPicWidth",
      "description": "获取当前 ROI 宽度。",
      "description_en": "Get the current ROI width."
    },
    {
      "action_name": "auto-GetPicHeight",
      "description": "获取当前 ROI 高度。",
      "description_en": "Get the current ROI height."
    },
    {
      "action_name": "auto-SetHorizBin",
      "description": "设置水平像素合并。",
      "description_en": "Set horizontal binning."
    },
    {
      "action_name": "auto-GetHorizBin",
      "description": "获取水平像素合并设置。",
      "description_en": "Get the horizontal binning setting."
    },
    {
      "action_name": "auto-GetHorzBinValue",
      "description": "获取水平像素合并值。",
      "description_en": "Get the horizontal binning value."
    },
    {
      "action_name": "auto-SetVertBin",
      "description": "设置垂直像素合并。",
      "description_en": "Set vertical binning."
    },
    {
      "action_name": "auto-GetVertBin",
      "description": "获取垂直像素合并设置。",
      "description_en": "Get the vertical binning setting."
    },
    {
      "action_name": "auto-SetROIIndex",
      "description": "通过索引选择 ROI。",
      "description_en": "Select the ROI by index."
    },
    {
      "action_name": "auto-SetROI",
      "description": "按坐标设置 ROI。",
      "description_en": "Set the ROI by coordinates."
    },
    {
      "action_name": "auto-GetROIX1",
      "description": "获取 ROI 左边界坐标。",
      "description_en": "Get the left ROI boundary coordinate."
    },
    {
      "action_name": "auto-GetROIX2",
      "description": "获取 ROI 右边界坐标。",
      "description_en": "Get the right ROI boundary coordinate."
    },
    {
      "action_name": "auto-GetROIY1",
      "description": "获取 ROI 上边界坐标。",
      "description_en": "Get the top ROI boundary coordinate."
    },
    {
      "action_name": "auto-GetROIY2",
      "description": "获取 ROI 下边界坐标。",
      "description_en": "Get the bottom ROI boundary coordinate."
    },
    {
      "action_name": "auto-SetEMGain",
      "description": "设置电子倍增增益。",
      "description_en": "Set the electron-multiplying gain."
    },
    {
      "action_name": "auto-GetEMGain",
      "description": "获取电子倍增增益设置。",
      "description_en": "Get the electron-multiplying gain setting."
    },
    {
      "action_name": "auto-GetElectrTemp",
      "description": "获取相机内部电子学温度。",
      "description_en": "Get the internal electronics temperature."
    },
    {
      "action_name": "auto-GetCCDTemp",
      "description": "获取传感器温度。",
      "description_en": "Get the sensor temperature."
    },
    {
      "action_name": "auto-GetCCDTempSetPoint",
      "description": "获取相机目标温度设定值。",
      "description_en": "Get the target camera temperature setpoint."
    },
    {
      "action_name": "auto-SetCCDTemp",
      "description": "设置相机目标温度。",
      "description_en": "Set the target camera temperature."
    },
    {
      "action_name": "auto-SetShutter",
      "description": "设置快门开关状态。",
      "description_en": "Set the shutter state."
    },
    {
      "action_name": "auto-SetBaselineClamp",
      "description": "设置基线钳位。",
      "description_en": "Set the baseline clamp."
    },
    {
      "action_name": "auto-GetAcquisitionMode",
      "description": "获取采集模式。",
      "description_en": "Get the acquisition mode."
    },
    {
      "action_name": "auto-SetAcquisitionMode",
      "description": "设置采集模式。",
      "description_en": "Set the acquisition mode."
    },
    {
      "action_name": "auto-SetBurst",
      "description": "设置突发采集参数。",
      "description_en": "Set burst acquisition parameters."
    },
    {
      "action_name": "auto-SetActive",
      "description": "设置相机对象是否处于活动状态。",
      "description_en": "Set whether the camera object is active."
    },
    {
      "action_name": "auto-StartExposure",
      "description": "开始曝光或采集。",
      "description_en": "Start exposure or acquisition."
    },
    {
      "action_name": "auto-StopAq",
      "description": "停止采集。",
      "description_en": "Stop acquisition."
    },
    {
      "action_name": "auto-GetNumImsBuffered",
      "description": "获取缓冲区中的图像数量。",
      "description_en": "Get the number of images in the buffer."
    },
    {
      "action_name": "auto-GetBufferSize",
      "description": "获取缓冲区总容量。",
      "description_en": "Get the total buffer capacity."
    },
    {
      "action_name": "auto-GetNoiseProperties",
      "description": "获取相机噪声参数。",
      "description_en": "Get the camera noise properties."
    },
    {
      "action_name": "auto-GetStatus",
      "description": "轮询相机状态信息。",
      "description_en": "Poll the camera for status information."
    },
    {
      "action_name": "auto-GetFPS",
      "description": "获取相机帧率。",
      "description_en": "Get the camera frame rate."
    },
    {
      "action_name": "auto-GenStartMetadata",
      "description": "生成采集开始时的相机元数据。",
      "description_en": "Generate camera metadata for acquisition start."
    },
    {
      "action_name": "auto-Shutdown",
      "description": "关闭并清理相机。",
      "description_en": "Shut down and clean up the camera."
    },
    {
      "action_name": "auto-CheckCoordinates",
      "description": "检查坐标或 ROI 是否有效（遗留接口）。",
      "description_en": "Check whether coordinates or ROI settings are valid (legacy interface)."
    },
    {
      "action_name": "auto-DisplayError",
      "description": "显示错误信息（遗留接口）。",
      "description_en": "Display an error message (legacy interface)."
    },
    {
      "action_name": "auto-GetBWPicture",
      "description": "获取黑白图像（遗留接口）。",
      "description_en": "Get a monochrome image (legacy interface)."
    },
    {
      "action_name": "auto-GetNumberChannels",
      "description": "获取颜色通道数（遗留接口）。",
      "description_en": "Get the number of color channels (legacy interface)."
    },
    {
      "action_name": "auto-SetCOC",
      "description": "设置 COC 兼容参数（遗留接口）。",
      "description_en": "Set a legacy COC compatibility parameter."
    },
    {
      "action_name": "auto-StartLifePreview",
      "description": "启动实时预览（遗留接口）。",
      "description_en": "Start live preview (legacy interface)."
    },
    {
      "action_name": "auto-StopLifePreview",
      "description": "停止实时预览（遗留接口）。",
      "description_en": "Stop live preview (legacy interface)."
    }
  ],
  "tag_hints": [
    "scientific camera",
    "microscopy imaging",
    "exposure control",
    "ROI readout",
    "sensor cooling",
    "image buffer acquisition",
    "camera frame rate"
  ]
}

